61	  customer: { yearsWithMHPCO: number };
62	  steps: Step[];
63	};
64	
65	type QuoteResult = {
66	  premium: number;
67	};
68	
69	type ClaimResult = {
70	  payout: number;
71	  remainingCap: number;
72	};
73	
74	type StepResult = QuoteResult | ClaimResult;
75	
76	type ScenarioOutput = {
77	  results: StepResult[];
78	};
79	
80	const isComponent = (item: Item): boolean =>
81	  item.type in COMPONENT_BASE_PREMIUM_BY_TYPE;
82	
83	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
84	  sameTypeItems.length === COMPONENT_BLOCK_SIZE &&
85	  sameTypeItems.every(isComponent);
86	
87	const groupByType = (items: Item[]): Item[][] => {
88	  const groups = new Map<string, Item[]>();
89	  for (const item of items) {
90	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
91	  }
92	  return [...groups.values()];
93	};
94	
95	const basePremiumForItem = (item: Item): number =>
96	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
97	
98	const basePremiumForGroup = (sameTypeItems: Item[]): number => {
99	  if (isComponentBlock(sameTypeItems)) return COMPONENT_BLOCK_BASE_PREMIUM;
100	  return sameTypeItems.reduce(
101	    (total, item) => total + basePremiumForItem(item),
102	    0,
103	  );
104	};
105	
106	const basePremiumForItems = (items: Item[]): number =>
107	  groupByType(items).reduce(
108	    (total, group) => total + basePremiumForGroup(group),
109	    0,
110	  );
111	
112	const amountAtRate = (
113	  basePremium: number,
114	  rate: number,
115	  applies?: boolean,
116	): number => (applies ? basePremium * rate : 0);
117	
118	const cursedSurcharge = (item: Item): number =>
119	  amountAtRate(basePremiumForItem(item), CURSED_SURCHARGE_RATE, item.cursed);
120	
121	const enchantmentLevelOf = (item: Item | undefined): number =>
