143	
144	const isLoyalCustomer = (yearsWithMHPCO: number): boolean =>
145	  yearsWithMHPCO >= LOYALTY_MINIMUM_YEARS;
146	
147	const loyaltyDiscount = (basePremium: number, yearsWithMHPCO: number): number =>
148	  amountAtRate(
149	    basePremium,
