151	    isLoyalCustomer(yearsWithMHPCO),
152	  );
153	
154	const followUpDiscount = (basePremium: number, isFollowUp: boolean): number =>
155	  amountAtRate(basePremium, FOLLOW_UP_DISCOUNT_RATE, isFollowUp);
156	
157	const premiumBeforeProcessingFee = (
158	  items: Item[],
159	  yearsWithMHPCO: number,
160	  isFollowUp: boolean,
161	): number => {
162	  const basePremium = basePremiumForItems(items);
163	  return (
164	    basePremium +
165	    totalItemSurcharges(items) +
166	    firstInsuranceSurcharge(basePremium) -
167	    loyaltyDiscount(basePremium, yearsWithMHPCO) -
168	    followUpDiscount(basePremium, isFollowUp)
