170	};
171	
172	const isFollowUpQuote = (stepIndex: number): boolean => stepIndex > 0;
173	
174	const isClaimStep = (step: Step): boolean => step.op === "claim";
175	
176	const insuranceSumForItems = (items: Item[]): number =>
177	  items.reduce(
178	    (total, item) => total + INSURANCE_VALUE_BY_ITEM_TYPE[item.type],
179	    0,
180	  );
181	
182	const capForItems = (items: Item[]): number =>
183	  insuranceSumForItems(items) * CAP_MULTIPLIER;
184	
185	const damagedItemFor = (
186	  damage: Damage,
187	  policyItems: Item[],
188	): Item | undefined =>
189	  policyItems.find((item) => item.type === damage.itemType);
190	
191	const reimbursementRateFor = (item: Item | undefined): number =>
192	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
193	    ? HALF_REIMBURSEMENT_RATE
194	    : FULL_REIMBURSEMENT_RATE;
195	
196	const payoutForDamage = (damage: Damage, policyItems: Item[]): number =>
197	  damage.amount * reimbursementRateFor(damagedItemFor(damage, policyItems)) -
198	  DEDUCTIBLE;
199	
200	const totalPayoutForDamages = (damages: Damage[], policyItems: Item[]): number =>
201	  damages.reduce(
202	    (total, damage) => total + payoutForDamage(damage, policyItems),
203	    0,
204	  );
205	
206	const policyItemsFor = (step: Step, steps: Step[]): Item[] =>
207	  steps[step.policy ?? 0].items ?? [];
208	
209	const claimResultFor = (step: Step, steps: Step[]): ClaimResult => {
210	  const policyItems = policyItemsFor(step, steps);
211	  const cap = capForItems(policyItems);
212	  const payout = totalPayoutForDamages(
213	    step.incident?.damages ?? [],
214	    policyItems,
215	  );
216	  return { payout, remainingCap: cap - payout };
217	};
218	
219	const quoteResultFor = (
220	  step: Step,
221	  yearsWithMHPCO: number,
222	  stepIndex: number,
223	): QuoteResult => ({
224	  premium: Math.ceil(
225	    premiumBeforeProcessingFee(
226	      step.items ?? [],
227	      yearsWithMHPCO,
228	      isFollowUpQuote(stepIndex),
229	    ) + PROCESSING_FEE,
230	  ),
231	});
