233	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
234	  results: scenario.steps.map((step, stepIndex) =>
235	    isClaimStep(step)
236	      ? claimResultFor(step, scenario.steps)
237	      : quoteResultFor(step, scenario.customer.yearsWithMHPCO, stepIndex),
238	  ),
239	});
